+document.addEventListener('DOMContentLoaded', () => {
+    const trigger = document.querySelector('.trigger');
+    const dialog = document.getElementById('delete-dialog');
+    const cancelButton = document.getElementById('cancel-delete');
+    const confirmButton = document.getElementById('confirm-delete');
+
+    if (!trigger || !dialog || !cancelButton || !confirmButton) return;
+
+    // Open dialog
+    trigger.addEventListener('click', () => {
+        dialog.showModal();
+    });
+
+    // Close dialog on Cancel
+    cancelButton.addEventListener('click', () => {
+        dialog.close();
+    });
+
+    // "Confirm" action
+    confirmButton.addEventListener('click', () => {
+        console.log('Image deleted');
+        // In a real app, you'd perform the deletion here.
+        // For this demo, we'll just close the dialog and maybe show a message.
+        dialog.close();
+        
+        // Optional: remove the image card to simulate deletion
+        const imageCard = document.querySelector('.image-card');
+        if (imageCard) {
+            imageCard.style.opacity = '0.5';
+            imageCard.style.pointerEvents = 'none';
+            trigger.disabled = true;
+            trigger.textContent = 'Deleted';
+        }
+    });
+
+    // Close dialog when clicking the backdrop
+    dialog.addEventListener('click', (event) => {
+        const rect = dialog.getBoundingClientRect();
+        const isInDialog = (
+            rect.top <= event.clientY &&
+            event.clientY <= rect.top + rect.height &&
+            rect.left <= event.clientX &&
+            event.clientX <= rect.left + rect.width
+        );
+        if (!isInDialog) {
+            dialog.close();
+        }
+    });
+});
+
')

